/** How many headwords the API accepts in one generation job. */
export const MAX_WORDS = 50;

/**
 * Splits the textarea into headwords, one per line or comma separated.
 * Blanks and repeats are dropped so the batch matches what the user meant.
 */
export function parseWordList(input: string): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const part of input.split(/[\n,]/)) {
    const word = part.trim();
    const key = word.toLowerCase();
    if (word === '' || seen.has(key)) continue;
    seen.add(key);
    out.push(word);
  }
  return out.slice(0, MAX_WORDS);
}
